86	    repo_root: &Path,
87	    evicted_index: &EvictedFixtureIndex,
88	    owner_path: &Path,
89	    role: &str,
90	    artifact_path: &Path,
91	    recorded_sha256: &str,
92	    mismatches: &mut Vec<String>,
93	) {
94	    let artifact_path = artifact_path
95	        .to_str()
96	        .expect("artifact ref path must be UTF-8");
97	    let actual_sha256 = if let Some(indexed) = evicted_index.sha256_for(artifact_path) {
98	        indexed.to_string()
