121	fn collect_files_named(dir: &Path, file_name: &str, files: &mut Vec<PathBuf>) {
122	    for entry in fs::read_dir(dir).unwrap_or_else(|err| {
123	        panic!(
124	            "read directory {} while looking for {file_name}: {err}",
125	            dir.display()
126	        )
127	    }) {
128	        let entry = entry.expect("directory entry is readable");
129	        let path = entry.path();
130	        if path.is_dir() {
131	            collect_files_named(&path, file_name, files);
132	        } else if path.file_name().and_then(|name| name.to_str()) == Some(file_name) {
133	            files.push(path);
134	        }
135	    }
136	}
