138	fn read_json<T>(path: &Path) -> T
139	where
140	    T: for<'de> Deserialize<'de>,
141	{
142	    let bytes = fs::read(path).unwrap_or_else(|err| panic!("read JSON {}: {err}", path.display()));
143	    serde_json::from_slice(&bytes)
144	        .unwrap_or_else(|err| panic!("parse JSON {}: {err}", path.display()))
145	}
146	
147	fn sha256_file(path: &Path) -> String {
148	    use sha2::{Digest, Sha256};
149	
150	    format!(
151	        "{:x}",
152	        Sha256::digest(
153	            fs::read(path)
154	                .unwrap_or_else(|err| panic!("read file for hash {}: {err}", path.display()))
155	        )
156	    )
157	}
