58	
59	fn collect_artifact_refs(
60	    value: &Value,
61	    location: &str,
62	    artifact_refs: &mut Vec<ArtifactRefCandidate>,
63	) {
64	    match value {
65	        Value::Array(items) => {
66	            for (index, item) in items.iter().enumerate() {
67	                collect_artifact_refs(item, &format!("{location}[{index}]"), artifact_refs);
68	            }
69	        }
70	        Value::Object(object) => {
71	            if let Some(candidate) = artifact_ref_from_object(object, location) {
72	                artifact_refs.push(candidate);
73	            }
74	            if let Some(committed_input_hashes) = object.get("committed_input_hashes") {
75	                collect_committed_input_hash_refs(
76	                    committed_input_hashes,
77	                    &format!("{location}.committed_input_hashes"),
78	                    artifact_refs,
79	                );
80	            }
81	            for (key, child) in object {
82	                collect_artifact_refs(child, &format!("{location}.{key}"), artifact_refs);
83	            }
84	        }
85	        _ => {}
86	    }
87	}
88	
89	fn artifact_ref_from_object(
90	    object: &Map<String, Value>,
91	    location: &str,
92	) -> Option<ArtifactRefCandidate> {
93	    Some(ArtifactRefCandidate {
94	        role: string_field(object, "role")?.to_string(),
95	        path: string_field(object, "path")?.to_string(),
96	        sha256: string_field(object, "sha256")?.to_string(),
97	        location: location.to_string(),
