101	fn collect_committed_input_hash_refs(
102	    value: &Value,
103	    location: &str,
104	    artifact_refs: &mut Vec<ArtifactRefCandidate>,
105	) {
106	    let Some(object) = value.as_object() else {
107	        return;
108	    };
109	
110	    for (role, input_hash) in object {
111	        let Some(input_hash) = input_hash.as_object() else {
112	            continue;
113	        };
114	        let (Some(path), Some(sha256)) = (
115	            string_field(input_hash, "path"),
116	            string_field(input_hash, "sha256"),
117	        ) else {
118	            continue;
119	        };
120	        artifact_refs.push(ArtifactRefCandidate {
121	            role: format!("committed_input_hashes.{role}"),
122	            path: path.to_string(),
123	            sha256: sha256.to_string(),
124	            location: format!("{location}.{role}"),
125	        });
126	    }
127	}
128	
129	fn string_field<'a>(object: &'a Map<String, Value>, key: &str) -> Option<&'a str> {
130	    object.get(key)?.as_str()
131	}
132	
133	fn check_artifact_ref(
134	    repo_root: &Path,
135	    evicted_index: &EvictedFixtureIndex,
136	    owner_path: &Path,
137	    location: &str,
138	    role: &str,
139	    artifact_path: &str,
140	    recorded_sha256: &str,
141	    mismatches: &mut Vec<String>,
142	) {
143	    let artifact_path = match normalize_repo_path(artifact_path) {
144	        Ok(path) => path,
145	        Err(err) => {
146	            mismatches.push(format!(
147	                "{} {location} role {role} path {artifact_path} recorded {recorded_sha256} actual <invalid path: {err}>",
148	                owner_path
149	                    .strip_prefix(repo_root)
150	                    .unwrap_or(owner_path)
151	                    .display()
152	            ));
153	            return;
154	        }
155	    };
156	
157	    let actual_sha256 = actual_sha256(repo_root, evicted_index, &artifact_path);
158	
159	    if recorded_sha256 != actual_sha256 {
160	        mismatches.push(format!(
161	            "{} {location} role {role} path {artifact_path} recorded {recorded_sha256} actual {actual_sha256}",
162	            owner_path
163	                .strip_prefix(repo_root)
164	                .unwrap_or(owner_path)
165	                .display()
166	        ));
167	    }
168	}
169	
170	fn normalize_repo_path(path: &str) -> Result<String, String> {
171	    let path = path.strip_prefix("repo://").unwrap_or(path);
172	    let repo_path = Path::new(path);
173	
174	    if path.is_empty() {
175	        return Err("path is empty".to_string());
176	    }
177	    if path.contains("://") {
178	        return Err("path is not repo-relative".to_string());
179	    }
180	    if repo_path.is_absolute() {
181	        return Err("path is absolute".to_string());
182	    }
183	    if repo_path.components().any(|component| {
184	        matches!(
185	            component,
186	            std::path::Component::ParentDir | std::path::Component::RootDir
187	        )
188	    }) {
189	        return Err("path escapes repository root".to_string());
190	    }
191	
192	    Ok(path.to_string())
193	}
194	
195	fn actual_sha256(
196	    repo_root: &Path,
197	    evicted_index: &EvictedFixtureIndex,
198	    artifact_path: &str,
199	) -> String {
200	    if let Some(indexed) = evicted_index.sha256_for(artifact_path) {
201	        indexed.to_string()
202	    } else {
203	        sha256_file(&repo_root.join(artifact_path))
204	            .unwrap_or_else(|err| format!("<unreadable: {err}>"))
205	    }
206	}
207	
208	fn committed_reference_json_files(root: &Path) -> Vec<PathBuf> {
209	    let mut files = Vec::new();
210	    collect_json_files(root, &mut files);
211	    files.sort();
212	    files
213	}
214	
215	fn collect_json_files(dir: &Path, files: &mut Vec<PathBuf>) {
216	    for entry in fs::read_dir(dir).unwrap_or_else(|err| {
217	        panic!(
218	            "read directory {} while looking for reference JSON files: {err}",
219	            dir.display()
220	        )
221	    }) {
222	        let entry = entry.expect("directory entry is readable");
223	        let path = entry.path();
224	        if path.is_dir() {
225	            collect_json_files(&path, files);
226	        } else if path.extension().and_then(|name| name.to_str()) == Some("json") {
227	            files.push(path);
228	        }
229	    }
230	}
231	
232	fn read_json_value(path: &Path) -> Value {
233	    let bytes = fs::read(path).unwrap_or_else(|err| panic!("read JSON {}: {err}", path.display()));
234	    serde_json::from_slice(&bytes)
235	        .unwrap_or_else(|err| panic!("parse JSON {}: {err}", path.display()))
236	}
237	
238	fn sha256_file(path: &Path) -> Result<String, String> {
239	    use sha2::{Digest, Sha256};
240	
241	    let bytes = fs::read(path).map_err(|err| format!("{}: {err}", path.display()))?;
242	    Ok(format!("{:x}", Sha256::digest(bytes)))
243	}
